const fs = require('fs');
const { execFileSync } = require('child_process');

const src = `'use strict';

// Unit cube: 8 vertices, 12 triangles, wound CCW seen from outside (outward normals).
const CUBE_VERTICES = [
  [-0.5, -0.5, -0.5], // 0
  [ 0.5, -0.5, -0.5], // 1
  [ 0.5,  0.5, -0.5], // 2
  [-0.5,  0.5, -0.5], // 3
  [-0.5, -0.5,  0.5], // 4
  [ 0.5, -0.5,  0.5], // 5
  [ 0.5,  0.5,  0.5], // 6
  [-0.5,  0.5,  0.5]  // 7
];

const CUBE_FACES = [
  [0, 3, 2], [0, 2, 1], // -Z
  [4, 5, 6], [4, 6, 7], // +Z
  [1, 2, 6], [1, 6, 5], // +X
  [0, 4, 7], [0, 7, 3], // -X
  [3, 7, 6], [3, 6, 2], // +Y
  [0, 1, 5], [0, 5, 4]  // -Y
];

function cube(size) {
  if (size === undefined) size = 1;
  return {
    vertices: CUBE_VERTICES.map(function (v) { return [v[0] * size, v[1] * size, v[2] * size]; }),
    faces: CUBE_FACES.map(function (f) { return f.slice(); })
  };
}

function asVec(p) {
  if (Array.isArray(p)) return [Number(p[0]), Number(p[1]), Number(p[2])];
  return [Number(p.x), Number(p.y), Number(p.z)];
}
function sub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function cross(a, b) {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}
function dot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }

function facePoints(geometry, face) {
  const pool = geometry.vertices || geometry.positions || geometry.points || [];
  return face.map(function (f) {
    if (typeof f === 'number') return asVec(pool[f]);
    return asVec(f);
  });
}

function audit(geometry) {
  const faces = geometry.faces || geometry.indices || [];
  const pool = geometry.vertices || geometry.positions || geometry.points || [];

  let cx = 0, cy = 0, cz = 0, n = 0;
  if (pool.length) {
    for (let i = 0; i < pool.length; i++) {
      const p = asVec(pool[i]);
      cx += p[0]; cy += p[1]; cz += p[2]; n++;
    }
  } else {
    for (let i = 0; i < faces.length; i++) {
      const pts = facePoints(geometry, faces[i]);
      for (let j = 0; j < pts.length; j++) { cx += pts[j][0]; cy += pts[j][1]; cz += pts[j][2]; n++; }
    }
  }
  const center = n ? [cx / n, cy / n, cz / n] : [0, 0, 0];

  let total = 0, inwardFaces = 0;
  for (let i = 0; i < faces.length; i++) {
    const pts = facePoints(geometry, faces[i]);
    if (pts.length < 3) continue;
    total++;
    const a = pts[0], b = pts[1], c = pts[2];
    const normal = cross(sub(b, a), sub(c, a));
    const fc = [0, 0, 0];
    for (let j = 0; j < pts.length; j++) { fc[0] += pts[j][0]; fc[1] += pts[j][1]; fc[2] += pts[j][2]; }
    fc[0] /= pts.length; fc[1] /= pts.length; fc[2] /= pts.length;
    const outward = sub(fc, center);
    if (dot(normal, outward) < 0) inwardFaces++;
  }

  return {
    faces: total,
    inwardFaces: inwardFaces,
    facesOutwardRatio: total === 0 ? 1 : (total - inwardFaces) / total
  };
}

function main() {
  const geometry = cube(1);
  const report = audit(geometry);
  console.log(JSON.stringify(report));
  console.log('vertices=' + geometry.vertices.length + ' triangles=' + geometry.faces.length);
  return report;
}

if (require.main === module) main();

module.exports = { audit: audit, cube: cube, CUBE_VERTICES: CUBE_VERTICES, CUBE_FACES: CUBE_FACES };
`;

fs.writeFileSync('normals.js', src);

const out = execFileSync(process.execPath, ['normals.js'], { cwd: process.cwd(), encoding: 'utf8' });
process.stdout.write(out);

let found = null;
const lines = out.split(/\r?\n/);
for (let i = 0; i < lines.length; i++) {
  const t = lines[i].trim();
  if (!t.startsWith('{')) continue;
  try {
    const o = JSON.parse(t);
    if (typeof o.faces === 'number' && typeof o.inwardFaces === 'number' && typeof o.facesOutwardRatio === 'number') { found = o; break; }
  } catch (e) { /* not JSON */ }
}

if (found && found.faces === 12 && found.inwardFaces === 0 && found.facesOutwardRatio === 1) {
  console.log('DONE: normals.js written and audit verified ' + JSON.stringify(found));
} else {
  console.log('FAIL: no valid audit JSON found in output');
  process.exitCode = 1;
}

