function dijkstra(g,s,t){
  const dist={},prev={},seen={};
  for(const k of Object.keys(g))dist[k]=Infinity;
  dist[s]=0;
  while(true){
    let u=null;for(const k of Object.keys(dist))if(!seen[k]&&(u===null||dist[k]<dist[u]))u=k;
