const fs = require('fs'), cp = require('child_process');
const p = (...a) => console.log(...a);

/* ---------- 阶段一：环境与现状（只读，不改无关文件） ---------- */
p('=== 阶段一：确认环境与现状 ===');
p('pwd =', process.cwd());
p('ls -a =', fs.readdirSync('.', { withFileTypes: true })
  .map(d => d.name + (d.isDirectory() ? '/' : '')).join('  '));
p('node -v =', process.version, '| execPath =', process.execPath);
if (fs.existsSync('package.json')) {
  let t = 'UNPARSEABLE';
  try { t = JSON.parse(fs.readFileSync('package.json', 'utf8')).type || '(missing)'; } catch (e) {}
  p('package.json 存在，type =', t, '=> 不修改它；cli.js 写成无 import/require 的形式，两种模式都能跑');
} else p('package.json 不存在 => 默认 CommonJS 语境，仍写成无依赖形式');
const existed = fs.existsSync('cli.js');
if (existed) {
  p('cli.js 已存在，改动前先读原内容：');
  p('----- cli.js 原内容 begin -----');
  p(fs.readFileSync('cli.js', 'utf8'));
  p('----- cli.js 原内容 end -----');
} else p('cli.js 不存在，将新建');

/* ---------- 阶段二：实现 cli.js ---------- */
const SRC = `const argv = process.argv.slice(2);
let name = 'anon';
let count = 1;
let verbose = false;
let unknown = null;

for (const arg of argv) {
  if (arg.startsWith('--name=')) {
    name = arg.slice('--name='.length);
  } else if (arg.startsWith('--count=')) {
    count = arg.slice('--count='.length);
  } else if (arg === '--verbose') {
    verbose = true;
  } else if (unknown === null) {
    unknown = arg;
  }
}

if (unknown !== null) {
  process.stderr.write('unknown flag: ' + unknown + '\\n');
  process.exit(2);
}

process.stdout.write('name=' + name + ' count=' + count + ' verbose=' + (verbose ? 'true' : 'false') + '\\n');
`;
fs.writeFileSync('cli.js', SRC);
p('=== 阶段二：已写入 cli.js（' + Buffer.byteLength(SRC) + ' bytes，仅用标准库）===');
p('规则：--name= / --count= 前缀取值，--verbose 置 true，其余进 unknown；unknown 优先 -> stderr + exit 2；无校验、无颜色、无 usage。');

/* ---------- 阶段三：实测取证 ---------- */
p('=== 阶段三：实测取证（真实执行，逐条分开贴 stdout / stderr / exit code）===');
const cases = [
  ['node cli.js --name=X --count=N --verbose', ['cli.js', '--name=X', '--count=N', '--verbose']],
  ['node cli.js', ['cli.js']],
  ['node cli.js --bogus', ['cli.js', '--bogus']],
];
const checks = [
