'use strict';
const fs = require('fs');
const { spawnSync } = require('child_process');

const SOURCE = `'use strict';

// Convention (chosen as the most conservative one, documented in the delivery notes):
// A triangular face counts as "outward" iff its right-hand-rule normal
// n = cross(B-A, C-A) (i.e. CCW winding when seen from outside) points away from
// the solid interior. Direction test: dot(n, faceCentroid - meshCentroid) > 0.
// If that dot is ~0 (ambiguous), fall back to the AABB center; if still ambiguous,
// or the face is degenerate (zero-length normal), the face is counted as NOT outward.
// The cube below is wound CCW-from-outside, so all 12 faces are outward.

function createCube() {
  const s = 1; // edge length
  const vertices = [
    [0, 0, 0], [s, 0, 0], [s, s, 0], [0, s, 0],
    [0, 0, s], [s, 0, s], [s, s, s], [0, s, s]
  ];
  const faces = [
    [0, 3, 2], [0, 2, 1], // z = 0  -> n = (0, 0, -1)
    [4, 5, 6], [4, 6, 7], // z = s  -> n = (0, 0,  1)
    [0, 1, 5], [0, 5, 4], // y = 0  -> n = (0, -1, 0)
    [2, 3, 7], [2, 7, 6], // y = s  -> n = (0,  1, 0)
    [0, 7, 3], [0, 4, 7], // x = 0  -> n = (-1, 0, 0)
    [1, 2, 6], [1, 6, 5]  // x = s  -> n = ( 1, 0, 0)
  ];
  return { vertices, faces };
}

function sub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function cross(u, v) {
  return [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
}
function dot(u, v) { return u[0] * v[0] + u[1] * v[1] + u[2] * v[2]; }

function meshCentroid(vertices) {
  const c = [0, 0, 0];
  for (const v of vertices) { c[0] += v[0]; c[1] += v[1]; c[2] += v[2]; }
  const n = vertices.length || 1;
  return [c[0] / n, c[1] / n, c[2] / n];
}

function aabbCenter(vertices) {
  const mn = [Infinity, Infinity, Infinity];
  const mx = [-Infinity, -Infinity, -Infinity];
  for (const v of vertices) {
    for (let i = 0; i < 3; i++) {
      if (v[i] < mn[i]) mn[i] = v[i];
      if (v[i] > mx[i]) mx[i] = v[i];
    }
  }
  return [(mn[0] + mx[0]) / 2, (mn[1] + mx[1]) / 2, (mn[2] + mx[2]) / 2];
}

function audit(geometry) {
  const vertices = (geometry && geometry.vertices) || [];
  const tris = (geometry && geometry.faces) || [];
  const centroid = meshCentroid(vertices);
  const boxCenter = aabbCenter(vertices);

  let faces = 0;
  let inwardFaces = 0;

  for (const f of tris) {
    faces += 1;
    const A = vertices[f[0]];
    const B = vertices[f[1]];
    const C = vertices[f[2]];
    if (!A || !B || !C) { inwardFaces += 1; continue; }

    const n = cross(sub(B, A), sub(C, A));
    const len = Math.sqrt(dot(n, n));
    if (!(len > 1e-12)) { inwardFaces += 1; continue; } // degenerate: not provably outward

    const fc = [(A[0] + B[0] + C[0]) / 3, (A[1] + B[1] + C[1]) / 3, (A[2] + B[2] + C[2]) / 3];
    let d = dot(n, sub(fc, centroid));
    if (Math.abs(d) <= 1e-9 * len) d = dot(n, sub(fc, boxCenter));

    if (!(d > 1e-9 * len)) inwardFaces += 1;
  }

  const facesOutwardRatio = faces === 0 ? 0 : (faces - inwardFaces) / faces;
  return { faces: faces, inwardFaces: inwardFaces, facesOutwardRatio: facesOutwardRatio };
}

function main() {
  console.log(JSON.stringify(audit(createCube())));
}

if (require.main === module) main();

module.exports = { createCube: createCube, audit: audit };
`;

