const fs = require('fs');
const { spawnSync } = require('child_process');

const SRC = `const EDGES = [
  ["A", "B", 4],
  ["A", "C", 2],
  ["C", "B", 1],
  ["B", "D", 5],
  ["C", "D", 8],
  ["D", "E", 2],
  ["C", "E", 10],
];

const adj = new Map();
for (const [u, v, w] of EDGES) {
  if (!adj.has(u)) adj.set(u, []);
  if (!adj.has(v)) adj.set(v, []);
  adj.get(u).push([v, w]);
  adj.get(v).push([u, w]);
}

const START = "A";
const GOAL = "E";

const dist = new Map();
const prev = new Map();
for (const n of adj.keys()) dist.set(n, Infinity);
dist.set(START, 0);

const done = new Set();
while (true) {
  let u = null;
  let best = Infinity;
  for (const [n, d] of dist) {
    if (!done.has(n) && d < best) {
      best = d;
      u = n;
    }
  }
  if (u === null) break;
  done.add(u);
  for (const [v, w] of adj.get(u)) {
    const nd = dist.get(u) + w;
    if (nd < dist.get(v)) {
      dist.set(v, nd);
      prev.set(v, u);
    }
  }
}

const path = [];
for (let cur = GOAL; cur !== undefined; cur = prev.get(cur)) {
  path.push(cur);
  if (cur === START) break;
}
path.reverse();

process.stdout.write(JSON.stringify({ dist: dist.get(GOAL), path }) + "\\n");
`;

fs.writeFileSync('path.js', SRC);

const r = spawnSync(process.execPath, ['path.js'], { encoding: 'utf8' });
const out = r.stdout;
const errs = [];
if (r.status !== 0) errs.push('exit code ' + r.status);
if (r.stderr && r.stderr.trim() !== '') errs.push('stderr: ' + r.stderr.trim());

const lines = out.split('\n');
if (lines[lines.length - 1] === '') lines.pop();
if (lines.length !== 1) errs.push('stdout lines = ' + lines.length);

let obj = null;
try {
  obj = JSON.parse(out.trim());
} catch (e) {
  errs.push('JSON.parse failed: ' + e.message);
}

const WEIGHTS = {
  'A-B': 4, 'A-C': 2, 'C-B': 1, 'B-D': 5,
  'C-D': 8, 'D-E': 2, 'C-E': 10,
};
const w = (a, b) => WEIGHTS[a + '-' + b] ?? WEIGHTS[b + '-' + a];

if (obj) {
  const keys = Object.keys(obj).sort();
  if (keys.length !== 2 || keys[0] !== 'dist' || keys[1] !== 'path') errs.push('keys = ' + keys.join(','));
  if (typeof obj.dist !== 'number' || obj.dist !== 10) errs.push('dist = ' + JSON.stringify(obj.dist));
  const exp = ['A', 'C', 'B', 'D', 'E'];
  if (!Array.isArray(obj.path) || obj.path.length !== exp.length ||
      obj.path.some((s, i) => typeof s !== 'string' || s !== exp[i])) {
    errs.push('path = ' + JSON.stringify(obj.path));
  } else {
    let sum = 0;
    for (let i = 0; i + 1 < obj.path.length; i++) {
      const ww = w(obj.path[i], obj.path[i + 1]);
      if (ww === undefined) errs.push('missing edge ' + obj.path[i] + '-' + obj.path[i + 1]);
      else sum += ww;
    }
    if (sum !== obj.dist) errs.push('sum ' + sum + ' != dist ' + obj.dist);
  }
}

if (errs.length) {
  console.log('FAIL: ' + errs.join(' | '));
} else {
  console.log('OK: ' + out.trim());
  console.log('DONE: path.js implements Dijkstra and passes all checks');
}

